import sys
from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

class LinkedListNode:
    def __init__(self, data):
        self.data_ = data
        self.next = None

def convert(head):
    if not head:
        return None

    nodes = []
    curr = head
    while curr:
        nodes.append(curr.data_)
        curr = curr.next

    n = len(nodes)
    if n == 0:
        return None

    root = Node(nodes[0])
    queue = deque([root])
    idx = 1

    while queue and idx < n:
        current = queue.popleft()

        if idx < n:
            current.left = Node(nodes[idx])
            queue.append(current.left)
            idx += 1

        if idx < n:
            current.right = Node(nodes[idx])
            queue.append(current.right)
            idx += 1

    return root

def print_level_order(root):
    if not root:
        return

    queue = deque([root])
    result = []

    while queue:
        node = queue.popleft()
        result.append(str(node.data))
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    print(" ".join(result))

def main():
    try:
        line1 = sys.stdin.readline().strip()
        if not line1:
            return
        n = int(line1)

        line2 = sys.stdin.readline().strip()
        if not line2:
            return
        parts = list(map(int, line2.split()))

        if not parts:
            return

        head = None
        tail = None
        for val in parts:
            new_node = LinkedListNode(val)
            if not head:
                head = new_node
                tail = new_node
            else:
                tail.next = new_node
                tail = new_node

        root = convert(head)
        print_level_order(root)
    except Exception:
        pass

if __name__ == "__main__":
    main()
